//! Builtin safety metadata queried from PostgreSQL 18.6 (Homebrew).
//! Full routine-query SQL SHA256: 9a2acb1f1c877228c99717fdc27da8c8bcbb4963e97ab31a03c388510ab14cb4
//! Full routine JSON SHA256: f8e3b1cfb54af43d88f32eae955653b5ea5b51f631cf454781fc46a39b2c7ec1
//! This metadata classifies expressions; it does not add executable routines.
//!
//! inventory.sql SHA256: d34882687670c4f607f3ee142123c4322b7597849cc2c8d8cde7c8ea596342d7
//! types.sql SHA256: a879092309e4e512e6b91e73354c1fa0b4c1878ea80a6f2daeb1810f238a77f2
//! inventory.json SHA256: f0225bd0a3e480c39e9fb5b4da323b52ee153916959c68a1a76b96afa7cd3747
//!
//! Cast OIDs (the `oid` of each `CASTS` row) come from a separate query,
//! shown after the extraction queries below.
//! Cast-OID query SHA256: c33311ff8b326ef6fcfa187535d6a795900f1892884db024603f1c2be97914b4
//! Cast-OID JSON SHA256: da099a97d6f91855cab690c182f2a8816f06370572de0339f8fcf57f8960a540
//!
//! Reference catalog definitions:
//! https://github.com/postgres/postgres/blob/REL_18_6/src/include/catalog/pg_proc.dat
//! https://github.com/postgres/postgres/blob/REL_18_6/src/include/catalog/pg_cast.dat
//! https://github.com/postgres/postgres/blob/REL_18_6/src/include/catalog/pg_type.dat

/* Exact extraction queries (each terminated by its original newline):
SELECT jsonb_build_object(
'leakproof',(SELECT jsonb_agg(jsonb_build_object('oid',oid::integer,'name',proname,'arguments',proargtypes::text,'language',prolang::integer,'volatility',provolatile::text) ORDER BY oid) FROM pg_proc WHERE proleakproof),
'procedures',(SELECT jsonb_agg(jsonb_build_object('oid',oid::integer,'name',proname,'arguments',proargtypes::text,'volatility',provolatile::text,'leakproof',proleakproof) ORDER BY oid) FROM pg_proc WHERE oid IN (SELECT oprcode FROM pg_operator UNION SELECT castfunc FROM pg_cast UNION SELECT typinput FROM pg_type UNION SELECT typoutput FROM pg_type)),
'operators',(SELECT jsonb_agg(jsonb_build_object('oid',o.oid::integer,'name',o.oprname,'left',o.oprleft::integer,'right',o.oprright::integer,'procedure',o.oprcode::oid::integer,'volatility',p.provolatile::text,'leakproof',p.proleakproof) ORDER BY o.oid) FROM pg_operator o JOIN pg_proc p ON p.oid=o.oprcode WHERE o.oprnamespace='pg_catalog'::regnamespace),
'casts',(SELECT jsonb_agg(jsonb_build_object('source',c.castsource::integer,'target',c.casttarget::integer,'procedure',c.castfunc::oid::integer,'method',c.castmethod::text,'context',c.castcontext::text,'output',s.typoutput::oid::integer,'input',t.typinput::oid::integer) ORDER BY c.castsource,c.casttarget) FROM pg_cast c JOIN pg_type s ON s.oid=c.castsource JOIN pg_type t ON t.oid=c.casttarget));
SELECT jsonb_agg(jsonb_build_object('oid',oid::integer,'input',typinput::oid::integer,'output',typoutput::oid::integer) ORDER BY oid) FROM pg_type WHERE typnamespace='pg_catalog'::regnamespace;
SELECT jsonb_agg(jsonb_build_object('oid',oid::integer,'name',proname,'arguments',proargtypes::text,'argument_count',pronargs,'volatility',provolatile::text,'leakproof',proleakproof) ORDER BY proname,proargtypes::text,oid) FROM pg_proc WHERE pronamespace='pg_catalog'::regnamespace;
SELECT jsonb_agg(jsonb_build_object('oid',oid::integer,'source',castsource::integer,'target',casttarget::integer) ORDER BY castsource,casttarget) FROM pg_cast;
`CASTS` is listed in cast-OID order, PostgreSQL's catalog order.
*/

